statement.sql:
;WITH MainTable AS ( SELECT U.UserId ,R.RoleAbbr ,STUFF(( SELECT ', ' + RoleAbbr FROM AC_Role R2 JOIN AC_RelUserRole UR2 ON R2.RoleId = UR2.RoleId AND UR2.UserId = U.UserId WHERE R2.ParentRoleId = R.RoleId FOR XML PATH ('') ), 1, 1, '') AS WorkAreas FROM AC_User U JOIN AC_RelUserRole UR ON U.UserId = UR.UserId JOIN AC_Role R ON UR.RoleId = R.RoleId
NULL
) SELECT U.UserId, STUFF(( SELECT '|' + RoleAbbr + IIF(WorkAreas IS NULL, '',':' + WorkAreas) FROM MainTable MT WHERE MT.UserId = U.UserId FOR XML PATH ('') ), 1, 1, '') AS Role_WorkAreas FROM AC_User U
